use std::collections::BTreeSet;

use chrono::Utc;
use loco_rs::prelude::*;
use sea_orm::sea_query::{extension::postgres::PgExpr, Expr};
use sea_orm::{DatabaseTransaction, QueryTrait, Select};
use serde_json::{json, Value};
use uuid::Uuid;

pub use super::_entities::articles::{self, ActiveModel, Entity, Model};

#[async_trait::async_trait]
impl ActiveModelBehavior for ActiveModel {
    async fn before_save<C>(mut self, _db: &C, insert: bool) -> std::result::Result<Self, DbErr>
    where
        C: ConnectionTrait,
    {
        if !insert {
            self.updated_at = Set(Utc::now().into());
        }
        Ok(self)
    }
}

impl Model {
    async fn page(
        db: &DatabaseConnection,
        query: Select<Entity>,
        limit: usize,
        offset: usize,
    ) -> std::result::Result<(Vec<Self>, usize), DbErr> {
        let count = query.clone().count(db).await? as usize;
        let articles = query
            .offset(offset as u64)
            .limit(limit as u64)
            .all(db)
            .await?;
        Ok((articles, count))
    }

    fn with_slug(slug: &str) -> Select<Entity> {
        Entity::find().filter(articles::Column::Slug.eq(slug))
    }

    fn published() -> Select<Entity> {
        Entity::find().filter(articles::Column::Status.eq("published"))
    }

    pub async fn by_slug<C: ConnectionTrait>(
        db: &C,
        slug: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Self::with_slug(slug).one(db).await
    }

    pub async fn by_slug_for_update(
        db: &DatabaseTransaction,
        slug: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Self::with_slug(slug).lock_exclusive().one(db).await
    }

    pub async fn create(
        db: &DatabaseConnection,
        author_id: i64,
        title: String,
        description: String,
        body: String,
        tags: Vec<String>,
        status: String,
    ) -> std::result::Result<Self, DbErr> {
        let published_at = (status == "published").then(|| Utc::now().into());
        ActiveModel {
            slug: Set(Self::slug_for(&title)),
            title: Set(title),
            description: Set(description),
            body: Set(body),
            tag_list: Set(serde_json::json!(tags)),
            author_id: Set(author_id),
            status: Set(status),
            published_at: Set(published_at),
            ..Default::default()
        }
        .insert(db)
        .await
    }

    pub fn tags(&self) -> Vec<String> {
        serde_json::from_value(self.tag_list.clone()).unwrap_or_default()
    }

    pub fn is_draft(&self) -> bool {
        self.status == "draft"
    }

    pub fn revised(&self) -> ActiveModel {
        let mut active = self.clone().into_active_model();
        active.revision = Set(self.revision + 1);
        active
    }

    pub fn publish(&self) -> ActiveModel {
        let mut active = self.revised();
        active.status = Set("published".to_owned());
        active.published_at = Set(Some(Utc::now().into()));
        active
    }

    pub fn slug_for(title: &str) -> String {
        format!("{}-{}", slug::slugify(title), Uuid::new_v4().simple())
    }

    pub async fn list(
        db: &DatabaseConnection,
        author: Option<&str>,
        favorited: Option<&str>,
        tag: Option<&str>,
        feed: Option<i64>,
        limit: usize,
        offset: usize,
    ) -> std::result::Result<(Vec<Self>, usize), DbErr> {
        use super::{favorites, follows, users};
        let mut query = Self::published().order_by_desc(articles::Column::Id);
        if let Some(username) = author {
            let ids = users::Entity::find()
                .select_only()
                .column(users::Column::Id)
                .filter(users::Column::Username.eq(username))
                .into_query();
            query = query.filter(articles::Column::AuthorId.in_subquery(ids));
        }
        if let Some(username) = favorited {
            let user_ids = users::Entity::find()
                .select_only()
                .column(users::Column::Id)
                .filter(users::Column::Username.eq(username))
                .into_query();
            let ids = favorites::Entity::find()
                .select_only()
                .column(favorites::Column::ArticleId)
                .filter(favorites::Column::UserId.in_subquery(user_ids))
                .into_query();
            query = query.filter(articles::Column::Id.in_subquery(ids));
        }
        if let Some(user_id) = feed {
            let ids = follows::Entity::find()
                .select_only()
                .column(follows::Column::FollowedId)
                .filter(follows::Column::FollowerId.eq(user_id))
                .into_query();
            query = query.filter(articles::Column::AuthorId.in_subquery(ids));
        }
        if let Some(tag) = tag {
            query = query.filter(Expr::col(articles::Column::TagList).contains(json!([tag])));
        }
        Self::page(db, query, limit, offset).await
    }

    pub async fn drafts(
        db: &DatabaseConnection,
        author_id: i64,
        limit: usize,
        offset: usize,
    ) -> std::result::Result<(Vec<Self>, usize), DbErr> {
        let query = Entity::find()
            .filter(articles::Column::AuthorId.eq(author_id))
            .filter(articles::Column::Status.eq("draft"))
            .order_by_desc(articles::Column::Id);
        Self::page(db, query, limit, offset).await
    }

    pub async fn all_tags(db: &DatabaseConnection) -> std::result::Result<BTreeSet<String>, DbErr> {
        Ok(Self::published()
            .select_only()
            .column(articles::Column::TagList)
            .into_tuple::<Value>()
            .all(db)
            .await?
            .into_iter()
            .flat_map(|tags| serde_json::from_value::<Vec<String>>(tags).unwrap_or_default())
            .collect())
    }
}

impl ActiveModel {
    pub fn replace_tags(mut self, tags: Vec<String>) -> Self {
        self.tag_list = Set(Value::from(tags));
        self
    }
}

use axum::{
    extract::{Json, Path, Query, State},
    http::StatusCode,
};
use loco_rs::prelude::*;
use sea_orm::DatabaseTransaction;
use serde::Deserialize;
use serde_json::{json, Value};

use crate::{
    controllers::api::{self, ApiError, ApiResult, OptionalViewer, Viewer},
    models::{articles, favorites, users},
    views::realworld::ArticleView,
};

#[derive(Default, Deserialize)]
pub struct ListQuery {
    tag: Option<String>,
    author: Option<String>,
    favorited: Option<String>,
    limit: Option<usize>,
    offset: Option<usize>,
}

impl ListQuery {
    fn page(&self) -> (usize, usize) {
        (self.limit.unwrap_or(20), self.offset.unwrap_or(0))
    }
}

#[derive(Deserialize)]
struct Envelope<T> {
    article: T,
}

#[derive(Deserialize)]
struct NewArticle {
    #[serde(default)]
    title: String,
    #[serde(default)]
    description: String,
    #[serde(default)]
    body: String,
    #[serde(default, rename = "tagList")]
    tag_list: Vec<String>,
    #[serde(default = "published_status")]
    status: Value,
}

fn published_status() -> Value {
    json!("published")
}

fn visible(
    article: Option<articles::Model>,
    viewer_id: Option<i64>,
) -> std::result::Result<articles::Model, ApiError> {
    let article = article.ok_or(ApiError::missing("article"))?;
    if article.is_draft() && Some(article.author_id) != viewer_id {
        return Err(ApiError::missing("article"));
    }
    Ok(article)
}

fn owned(
    article: articles::Model,
    viewer_id: i64,
) -> std::result::Result<articles::Model, ApiError> {
    if article.author_id != viewer_id {
        return Err(ApiError::forbidden("article"));
    }
    Ok(article)
}

pub async fn find(
    ctx: &AppContext,
    slug: &str,
    viewer_id: Option<i64>,
) -> std::result::Result<articles::Model, ApiError> {
    visible(articles::Model::by_slug(&ctx.db, slug).await?, viewer_id)
}

async fn find_owned_for_update(
    txn: &DatabaseTransaction,
    slug: &str,
    viewer_id: i64,
) -> std::result::Result<articles::Model, ApiError> {
    let article = articles::Model::by_slug_for_update(txn, slug).await?;
    owned(visible(article, Some(viewer_id))?, viewer_id)
}

pub fn interactable(article: &articles::Model) -> std::result::Result<(), ApiError> {
    if article.is_draft() {
        Err(ApiError::new(
            StatusCode::UNPROCESSABLE_ENTITY,
            "article",
            "is a draft",
        ))
    } else {
        Ok(())
    }
}

async fn single(
    ctx: &AppContext,
    article: &articles::Model,
    viewer: Option<&users::Model>,
    status: StatusCode,
) -> ApiResult {
    let article = ArticleView::load(&ctx.db, article, viewer, true).await?;
    Ok(api::json_response(status, json!({"article": article})))
}

async fn list_response(
    ctx: &AppContext,
    viewer: Option<&users::Model>,
    query: ListQuery,
    feed: bool,
) -> ApiResult {
    let (limit, offset) = query.page();
    let (articles, count) = articles::Model::list(
        &ctx.db,
        query.author.as_deref(),
        query.favorited.as_deref(),
        query.tag.as_deref(),
        if feed { viewer.map(|u| u.id) } else { None },
        limit,
        offset,
    )
    .await?;
    many(ctx, &articles, count, viewer).await
}

async fn many(
    ctx: &AppContext,
    articles: &[articles::Model],
    count: usize,
    viewer: Option<&users::Model>,
) -> ApiResult {
    let views = ArticleView::load_many(&ctx.db, articles, viewer).await?;
    Ok(api::json_response(
        StatusCode::OK,
        json!({"articles": views, "articlesCount": count}),
    ))
}

#[debug_handler]
async fn list(
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    list_response(&ctx, viewer.as_ref(), query, false).await
}

#[debug_handler]
async fn feed(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    list_response(&ctx, Some(&viewer), query, true).await
}

#[debug_handler]
async fn drafts(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    let (limit, offset) = query.page();
    let (articles, count) = articles::Model::drafts(&ctx.db, viewer.id, limit, offset).await?;
    many(&ctx, &articles, count, Some(&viewer)).await
}

#[debug_handler]
async fn show(
    Path(slug): Path<String>,
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = find(&ctx, &slug, viewer.as_ref().map(|user| user.id)).await?;
    single(&ctx, &article, viewer.as_ref(), StatusCode::OK).await
}

#[debug_handler]
async fn create(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { article }): Json<Envelope<NewArticle>>,
) -> ApiResult {
    api::required(&article.title, "title")?;
    api::required(&article.description, "description")?;
    api::required(&article.body, "body")?;
    let status = match article.status.as_str() {
        Some("draft") => "draft",
        Some("published") => "published",
        _ => return Err(ApiError::invalid("status")),
    };
    let article = articles::Model::create(
        &ctx.db,
        viewer.id,
        article.title,
        article.description,
        article.body,
        article.tag_list,
        status.to_owned(),
    )
    .await?;
    single(&ctx, &article, Some(&viewer), StatusCode::CREATED).await
}

fn changed_text(
    changes: &Value,
    field: &'static str,
) -> std::result::Result<Option<String>, ApiError> {
    changes
        .get(field)
        .map(|value| {
            let text = value.as_str().ok_or(ApiError::blank(field))?;
            api::required(text, field)?;
            Ok(text.to_owned())
        })
        .transpose()
}

#[debug_handler]
async fn update(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { article: changes }): Json<Envelope<Value>>,
) -> ApiResult {
    let txn = ctx.db.begin().await?;
    let article = find_owned_for_update(&txn, &slug, viewer.id).await?;
    if let Some(revision) = changes.get("revision") {
        if !revision.is_i64() && !revision.is_u64() {
            return Err(ApiError::invalid("revision"));
        }
        if *revision != json!(article.revision) {
            let current = ArticleView::load(&ctx.db, &article, Some(&viewer), true).await?;
            return Ok(api::json_response(
                StatusCode::CONFLICT,
                json!({"errors": {"revision": ["is stale"]}, "article": current}),
            ));
        }
    }
    let mut active = article.revised();
    if let Some(title) = changed_text(&changes, "title")? {
        active.slug = Set(articles::Model::slug_for(&title));
        active.title = Set(title);
    }
    if let Some(description) = changed_text(&changes, "description")? {
        active.description = Set(description);
    }
    if let Some(body) = changed_text(&changes, "body")? {
        active.body = Set(body);
    }
    if let Some(tags) = changes.get("tagList") {
        let tags: Vec<String> =
            serde_json::from_value(tags.clone()).map_err(|_| ApiError::invalid("tagList"))?;
        active = active.replace_tags(tags);
    }
    let article = active.update(&txn).await?;
    txn.commit().await?;
    single(&ctx, &article, Some(&viewer), StatusCode::OK).await
}

